import{_ as s,B as b,c as d,o,j as r,at as u,t as a,F as h,C as v,G as c,w as m,a as _}from"./chunks/framework.BlwsHpGA.js";const p="/img/hw-ui.svg",g="/img/hw_ui_screenshot.png",q=JSON.parse('{"title":"여정의 시작 - 통합","description":"흩어진 사내 컴포넌트를 하나의 공용 라이브러리로 통합","frontmatter":{"layout":"doc","title":"여정의 시작 - 통합","description":"흩어진 사내 컴포넌트를 하나의 공용 라이브러리로 통합","lastUpdated":true,"editLink":true,"navbar":true,"sidebar":true,"aside":true,"outline":"deep"},"headers":[],"relativePath":"beui/journey1.md","filePath":"beui/journey1.md"}'),w={name:"beui/journey1.md"},f=Object.assign(w,{setup(y){const n=["css","scss","gulp::build","components","vue","plugins"];return(t,e)=>{const l=b("BeButton");return o(),d("div",null,[r("h1",null,a(t.$frontmatter.title),1),r("p",null,a(t.$frontmatter.description),1),e[0]||(e[0]=u('<h2 id="문제" tabindex="-1" data-v-0b478176>문제 <a class="header-anchor" href="#문제" aria-label="Permalink to &quot;문제&quot;" data-v-0b478176>​</a></h2><ul data-v-0b478176><li data-v-0b478176>서비스마다 컴포넌트가 따로 관리 되었기 때문에, UI 패턴이 중복되고 유지보수가 어려움</li><li data-v-0b478176>외부 UI 컴포넌트 사용으로 발생한 스타일 커스텀의 한계와 무거운 라이브러리로 인한 성능 저하 문제 발생</li></ul><h2 id="목표" tabindex="-1" data-v-0b478176>목표 <a class="header-anchor" href="#목표" aria-label="Permalink to &quot;목표&quot;" data-v-0b478176>​</a></h2><ul data-v-0b478176><li data-v-0b478176>하나의 통합된 라이브러리로 만들어 유지 관리 비용을 줄이고 용어 명칭을 통일하여 관계부서와의 소통에 활용</li><li data-v-0b478176>부분적으로 사용중인 외부 라이브러리를 대체하고 내부 라이브러리로 통합하여 커스텀 자유도와 일관성 확보</li></ul><h2 id="hw-ui-component-hwui" tabindex="-1" data-v-0b478176><img src="'+p+'" alt="hw-ui" width="18" data-v-0b478176> hw-ui-component(HWUI) <a class="header-anchor" href="#hw-ui-component-hwui" aria-label="Permalink to &quot;![hw-ui](/img/hw-ui.svg){width=18} hw-ui-component(HWUI)&quot;" data-v-0b478176>​</a></h2><div class="main-image" data-v-0b478176><p data-v-0b478176><a href="https://noistommy.github.io/hw_ui/#/" target="_blank" rel="noreferrer" data-v-0b478176><img src="'+g+'" alt="test" data-v-0b478176></a></p></div><div class="caption" data-v-0b478176>hw-ui-component document site main</div><h3 id="프로젝트-내용" tabindex="-1" data-v-0b478176>프로젝트 내용 <a class="header-anchor" href="#프로젝트-내용" aria-label="Permalink to &quot;프로젝트 내용&quot;" data-v-0b478176>​</a></h3><ul data-v-0b478176><li data-v-0b478176>Vue2 기반 서비스에서 사용된 UI 컴포넌트를 모아 공용 컴포넌트 라이브러리로 통합함</li><li data-v-0b478176>시멘틱 네이밍을 통해 스타일 컨벤션을 정의하고 팀과 공유하기 위한 문서의 역할을 함</li><li data-v-0b478176>커스텀이 필요한 외부 컴포넌트를 대체 할 자체 컴포넌트를 구현함</li></ul><h3 id="링크" tabindex="-1" data-v-0b478176>링크 <a class="header-anchor" href="#링크" aria-label="Permalink to &quot;링크&quot;" data-v-0b478176>​</a></h3><table tabindex="0" data-v-0b478176><thead data-v-0b478176><tr data-v-0b478176><th data-v-0b478176>Name</th><th data-v-0b478176>URL</th></tr></thead><tbody data-v-0b478176><tr data-v-0b478176><td data-v-0b478176>Demo</td><td data-v-0b478176><a href="https://noistommy.github.io/hw_ui/#/" target="_blank" rel="noreferrer" data-v-0b478176>https://noistommy.github.io/hw_ui</a></td></tr><tr data-v-0b478176><td data-v-0b478176>Github</td><td data-v-0b478176><a href="https://github.com/noistommy/dev_hw_ui.git" target="_blank" rel="noreferrer" data-v-0b478176>https://github.com/noistommy/dev_hw_ui.git</a></td></tr></tbody></table><h2 id="결과" tabindex="-1" data-v-0b478176>결과 <a class="header-anchor" href="#결과" aria-label="Permalink to &quot;결과&quot;" data-v-0b478176>​</a></h2><ul data-v-0b478176><li data-v-0b478176>통합 라이브러리 사용으로 신규 서비스 개발과정에서 기존 서비스의 언어(용어) 기능정의 등을 그대로 사용함으로서 일정 단축 및 개발, 유지보수 최적화를 달성함</li></ul><h2 id="keyword" tabindex="-1" data-v-0b478176>Keyword <a class="header-anchor" href="#keyword" aria-label="Permalink to &quot;Keyword&quot;" data-v-0b478176>​</a></h2>',14)),(o(),d(h,null,v(n,i=>c(l,{key:i,outline:"",round:"",compact:""},{default:m(()=>[_(a(i),1)]),_:2},1024)),64))])}}}),x=s(f,[["__scopeId","data-v-0b478176"]]);export{q as __pageData,x as default};
